changeSet.sql:
INSERT INTO transaction ( uuid, transaction_number, other_identifiers, material_direction, material_to_be_returned, _group, purpose, transaction_type, status, opened_date, closed_date, due_date, remarks, shipment, managed_attributes, agent_roles, attachment, material_samples, created_by, created_on ) SELECT t.uuid, t.transaction_number, t.other_identifiers, t.material_direction::material_direction, COALESCE(t.material_to_be_returned, false), t._group, t.purpose, t.transaction_type, t.status, t.opened_date, t.closed_date, t.due_date, t.remarks, t.shipment, COALESCE(t.managed_attributes, '{}'), t.agent_roles, t.attachment, t.material_samples, t.created_by, t.created_on FROM loan_transaction_transaction t ORDER BY t.id;
INSERT INTO controlled_vocabulary_item ( controlled_vocabulary_id, uuid, name, _group, key, accepted_values, vocabulary_element_type, dina_component, multilingual_description, created_by, created_on ) SELECT (SELECT id FROM controlled_vocabulary WHERE uuid = '01998155-a6f0-7c2f-9fcc-994d74222f9c'), ma.uuid, ma.name, ma._group, ma.key, ma.accepted_values, ma.type, 'LOAN_TRANSACTION', ma.multilingual_description, ma.created_by, ma.created_on FROM loan_transaction_managed_attribute ma ORDER BY ma.created_on, ma.id ON CONFLICT (controlled_vocabulary_id, key, dina_component) DO NOTHING;
CREATE TEMPORARY TABLE loan_transaction_jv_offset AS SELECT (SELECT COALESCE(MAX(commit_pk), 0) FROM jv_commit) AS commit_pk_offset, (SELECT COALESCE(TRUNC(MAX(commit_id)), 0) FROM jv_commit) AS commit_id_offset, (SELECT COALESCE(MAX(global_id_pk), 0) FROM jv_global_id) AS global_id_pk_offset, (SELECT COALESCE(MAX(snapshot_pk), 0) FROM jv_snapshot) AS snapshot_pk_offset;
INSERT INTO jv_commit (commit_pk, author, commit_date, commit_date_instant, commit_id) SELECT c.commit_pk + o.commit_pk_offset, c.author, c.commit_date, c.commit_date_instant, c.commit_id + o.commit_id_offset FROM loan_transaction_jv_commit c CROSS JOIN loan_transaction_jv_offset o;
INSERT INTO jv_commit_property (property_name, property_value, commit_fk) SELECT p.property_name, p.property_value, p.commit_fk + o.commit_pk_offset FROM loan_transaction_jv_commit_property p CROSS JOIN loan_transaction_jv_offset o;
INSERT INTO jv_global_id (global_id_pk, local_id, fragment, type_name, owner_id_fk) SELECT g.global_id_pk + o.global_id_pk_offset, g.local_id, g.fragment, replace(g.type_name, 'ca.gc.aafc.transaction.api.entities.', 'ca.gc.aafc.collection.api.entities.'), g.owner_id_fk + o.global_id_pk_offset FROM loan_transaction_jv_global_id g CROSS JOIN loan_transaction_jv_offset o;
INSERT INTO jv_snapshot (snapshot_pk, type, version, state, changed_properties, managed_type, global_id_fk, commit_fk) SELECT s.snapshot_pk + o.snapshot_pk_offset, s.type, s.version, replace(s.state, 'ca.gc.aafc.transaction.api.entities.', 'ca.gc.aafc.collection.api.entities.'), s.changed_properties, replace(s.managed_type, 'ca.gc.aafc.transaction.api.entities.', 'ca.gc.aafc.collection.api.entities.'), s.global_id_fk + o.global_id_pk_offset, s.commit_fk + o.commit_pk_offset FROM loan_transaction_jv_snapshot s CROSS JOIN loan_transaction_jv_offset o;
SELECT setval('jv_commit_pk_seq', GREATEST((SELECT MAX(commit_pk) FROM jv_commit), (SELECT last_value FROM jv_commit_pk_seq))); SELECT setval('jv_global_id_pk_seq', GREATEST((SELECT MAX(global_id_pk) FROM jv_global_id), (SELECT last_value FROM jv_global_id_pk_seq))); SELECT setval('jv_snapshot_pk_seq', GREATEST((SELECT MAX(snapshot_pk) FROM jv_snapshot), (SELECT last_value FROM jv_snapshot_pk_seq)));

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM loan_transaction_transaction lt WHERE NOT EXISTS (SELECT 1 FROM transaction t WHERE t.uuid = lt.uuid)) THEN
    RAISE EXCEPTION 'Loan transaction migration: missing transaction';
  END IF;
  IF EXISTS (
    SELECT 1 FROM loan_transaction_managed_attribute ma
    WHERE NOT EXISTS (
      SELECT 1 FROM controlled_vocabulary_item cvi
        JOIN controlled_vocabulary cv ON cv.id = cvi.controlled_vocabulary_id
      WHERE cv.uuid = '01998155-a6f0-7c2f-9fcc-994d74222f9c'
        AND cvi.dina_component = 'LOAN_TRANSACTION' AND cvi.key = ma.key)) THEN
    RAISE EXCEPTION 'Loan transaction migration: missing managed attribute';
  END IF;
  IF (SELECT count(*) FROM jv_snapshot, loan_transaction_jv_offset o WHERE snapshot_pk > o.snapshot_pk_offset)
      <> (SELECT count(*) FROM loan_transaction_jv_snapshot) THEN
    RAISE EXCEPTION 'Loan transaction migration: audit snapshot count mismatch';
  END IF;
END $$;

DROP TABLE loan_transaction_jv_offset;
DROP TABLE loan_transaction_transaction;
DROP TABLE loan_transaction_managed_attribute;
DROP TABLE loan_transaction_jv_commit;
DROP TABLE loan_transaction_jv_commit_property;
DROP TABLE loan_transaction_jv_global_id;
DROP TABLE loan_transaction_jv_snapshot;
